SELECT DISTINCT BOOKSET_ID, BOOKSET_NAME , BOOKSET_FULLNAME FROM BOK_BOOKSET where 1=1
AND ACCT_SUBJECT_ID = #{prodId,jdbcType=VARCHAR}
order by BOOKSET_ID

SELECT COUNT(*) FROM ( SELECT B.VAL_DATE AS valDate,B.FINPROD_ID AS finprodId,B.FINPROD_NAME AS finprodName, SUM(B.CAPITAL） AS CAPITAL,SUM(B.ASSET_VALUE) AS assetValue,SUM(B.NET_UNIT_VALUE） AS netUnitValue, /**add by leipeng UAT-230 单位净值、累计净值、七日年化收益率、应付利润，值不应该一直为0 20180903*/ SUM(B.TAOTALNETVALUE) AS TAOTALNETVALUE,SUM(B.SEVENDAYRATE) AS SEVENDAYRATE,SUM(B.PAYPROFIT) AS PAYPROFIT FROM ( SELECT A.VAL_DATE AS VAL_DATE,A.FINPROD_ID AS FINPROD_ID,A.FINPROD_NAME AS FINPROD_NAME, CASE WHEN A.DETAIL_DIST = '01' AND SUBJECT_NO = '22320101' THEN DECODE(A.BAL_FLAG,'C',1,-1)*A.COST ELSE 0 END AS PAYPROFIT, CASE WHEN A.DETAIL_DIST = '02' THEN A.COST ELSE 0 END AS CAPITAL, DECODE(A.PROFIT_TYPE,'01',DECODE(A.DETAIL_DIST,'07',A.COST,0),'03',decode(A.DETAIL_DIST,'28',TO_NUMBER(A.SUBJECT_NAME),0),0) ASSET_VALUE, /**add by leipeng UAT-230 单位净值、累计净值、七日年化收益率、应付利润，值不应该一直为0 20180903*/ DECODE(A.PROFIT_TYPE,'01',DECODE(A.DETAIL_DIST,'08',TO_NUMBER(A.SUBJECT_NAME) ,0),'03',decode(A.DETAIL_DIST,'29',TO_NUMBER(A.SUBJECT_NAME),0),0) NET_UNIT_VALUE, CASE WHEN A.DETAIL_DIST = '17' THEN TO_NUMBER(A.SUBJECT_NAME) ELSE 0 END AS TAOTALNETVALUE, CASE WHEN A.DETAIL_DIST = '33' THEN TO_NUMBER(A.SUBJECT_NAME) ELSE 0 END AS SEVENDAYRATE FROM ( SELECT BVD.VAL_DATE AS VAL_DATE,BVD.COST AS COST,BVD.DETAIL_DIST AS DETAIL_DIST,BVD.SUBJECT_NO,BVD.SUBJECT_NAME, FP.FINPROD_ID AS FINPROD_ID,FP.FINPROD_NAME AS FINPROD_NAME ,FP.PROFIT_TYPE,BVD.BAL_FLAG FROM BOK_VAL_TABLE_DATA BVD JOIN BOK_BOOKSET BB ON BVD.BOOKSET_ID = BB.BOOKSET_ID JOIN FIN_PRODUCT FP ON BB.ACCT_SUBJECT_ID = FP.FINPROD_ID WHERE 1=1
AND BVD.VAL_DATE >= #{valDateBegin,jdbcType=DATE}
AND BVD.VAL_DATE <= #{valDateEnd,jdbcType=DATE}
AND BB.ACCT_SUBJECT_ID = #{prodId}
AND BVD.DETAIL_DIST IN ('01','02','07','08','17','28','29','33') ) A ) B GROUP BY B.VAL_DATE,B.FINPROD_ID,B.FINPROD_NAME )
